"use client";
// Additive adaptation of the existing CometaLink content editor; original source is preserved.
import type { InputHTMLAttributes, TextareaHTMLAttributes, ChangeEvent } from "react";
import AddIcon from "@mui/icons-material/Add";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutlined";
import type { SiteResponse } from "./shared/site";
import { CoverageMap } from "../coverage-map";
import { pageCopyLabel, pageCopySections } from "./shared/page-copy";
type Props = { site: SiteResponse; mutateSite: (change: (draft: SiteResponse) => void) => void; canWrite: boolean; busy: boolean };
function Glyph({ name }: { name: string }) { return name === "plus" ? <AddIcon fontSize="small"/> : <DeleteOutlineIcon fontSize="small"/>; }
function Input({ label, ...props }: InputHTMLAttributes<HTMLInputElement> & { label: string }) { return <label className="cmc-field"><span>{label}</span><input {...props}/></label>; }
function Textarea({ label, ...props }: TextareaHTMLAttributes<HTMLTextAreaElement> & { label: string }) { return <label className="cmc-field"><span>{label}</span><textarea {...props}/></label>; }
export function ContentEditor({ site, mutateSite, canWrite, busy }: Props) { return <><article className="cmc-panel cmc-editor" style={{ marginBottom: 28 }}><div className="cmc-panel-heading"><h3>Vista previa de cobertura</h3></div><CoverageMap towers={site.towers}/><p className="cmc-editor-help">Ubicación de las emisoras. La cobertura real requiere validación técnica.</p></article><fieldset className="cmc-content-fieldset" disabled={!canWrite || busy}><legend className="cmc-visually-hidden">Contenido de la página</legend><div className="cmc-editor-stack">
          <article className="cmc-panel cmc-editor"><div className="cmc-panel-heading"><div><h3>Empresa y canales de atención</h3></div><span className="cmc-tag">Sitio completo</span></div><div className="cmc-fields cols-3"><Input label="Marca" value={site.settings.company.brand} onChange={(e) => mutateSite((d) => { d.settings.company.brand = e.target.value; })}/><Input label="Razón social" value={site.settings.company.legalName} onChange={(e) => mutateSite((d) => { d.settings.company.legalName = e.target.value; })}/><Input label="RFC" value={site.settings.company.rfc} onChange={(e) => mutateSite((d) => { d.settings.company.rfc = e.target.value; })}/><Input label="WhatsApp (con código de país)" value={site.settings.company.whatsapp} onChange={(e) => mutateSite((d) => { d.settings.company.whatsapp = e.target.value; })}/><Input label="Correo general" type="email" value={site.settings.company.email} onChange={(e) => mutateSite((d) => { d.settings.company.email = e.target.value; })}/><Input label="Correo de soporte" type="email" value={site.settings.company.supportEmail} onChange={(e) => mutateSite((d) => { d.settings.company.supportEmail = e.target.value; })}/></div><div className="cmc-fields cols-2"><Textarea label="Domicilio" rows={3} value={site.settings.company.address} onChange={(e) => mutateSite((d) => { d.settings.company.address = e.target.value; })}/><div className="cmc-fields"><Input label="Horario entre semana" value={site.settings.company.hours.weekdays} onChange={(e) => mutateSite((d) => { d.settings.company.hours.weekdays = e.target.value; })}/><Input label="Horario de sábado" value={site.settings.company.hours.saturday} onChange={(e) => mutateSite((d) => { d.settings.company.hours.saturday = e.target.value; })}/></div></div><div className="cmc-fields cols-3"><Textarea label="Teléfonos de soporte (uno por línea)" rows={3} value={site.settings.company.general.support.join("\n")} onChange={(e) => mutateSite((d) => { d.settings.company.general.support = e.target.value.split("\n"); })}/><Textarea label="Teléfonos de pagos" rows={3} value={site.settings.company.general.payments.join("\n")} onChange={(e) => mutateSite((d) => { d.settings.company.general.payments = e.target.value.split("\n"); })}/><Textarea label="Teléfonos de ventas" rows={3} value={site.settings.company.general.sales.join("\n")} onChange={(e) => mutateSite((d) => { d.settings.company.general.sales = e.target.value.split("\n"); })}/></div></article>

          <article className="cmc-panel cmc-editor"><div className="cmc-panel-heading"><div><h3>Presentación comercial</h3></div></div><div className="cmc-fields cols-3"><Input label="Etiqueta de cobertura" value={site.settings.coverageKicker} onChange={(e) => mutateSite((d) => { d.settings.coverageKicker = e.target.value; })}/><Input label="Título de cobertura" value={site.settings.coverageTitle} onChange={(e) => mutateSite((d) => { d.settings.coverageTitle = e.target.value; })}/><Textarea label="Introducción de cobertura" rows={3} value={site.settings.coverageLead} onChange={(e) => mutateSite((d) => { d.settings.coverageLead = e.target.value; })}/><Textarea label="Introducción de servicios" rows={3} value={site.settings.servicesLead} onChange={(e) => mutateSite((d) => { d.settings.servicesLead = e.target.value; })}/><Textarea label="Introducción de planes" rows={3} value={site.settings.plansLead} onChange={(e) => mutateSite((d) => { d.settings.plansLead = e.target.value; })}/></div><div className="cmc-repeat-grid">{site.settings.heroSlides.map((slide, index) => <div className="cmc-repeat" key={index}><div><b>Diapositiva {index + 1}</b>{site.settings.heroSlides.length > 1 && <button type="button" aria-label={`Eliminar diapositiva ${index + 1}`} onClick={() => mutateSite((d) => { d.settings.heroSlides.splice(index, 1); })}><Glyph name="trash"/></button>}</div><Input label="Antetítulo" value={slide.eyebrow} onChange={(e) => mutateSite((d) => { d.settings.heroSlides[index].eyebrow = e.target.value; })}/><div className="cmc-fields cols-2"><Input label="Título" value={slide.title} onChange={(e) => mutateSite((d) => { d.settings.heroSlides[index].title = e.target.value; })}/><Input label="Texto destacado" value={slide.emphasis} onChange={(e) => mutateSite((d) => { d.settings.heroSlides[index].emphasis = e.target.value; })}/></div><Textarea label="Descripción" rows={3} value={slide.copy} onChange={(e) => mutateSite((d) => { d.settings.heroSlides[index].copy = e.target.value; })}/><div className="cmc-fields cols-2"><Input label="Imagen" value={slide.image} onChange={(e) => mutateSite((d) => { d.settings.heroSlides[index].image = e.target.value; })}/><Input label="Descripción accesible de la imagen" value={slide.imageAlt} onChange={(e) => mutateSite((d) => { d.settings.heroSlides[index].imageAlt = e.target.value; })}/><Input label="Distintivo" value={slide.badge} onChange={(e) => mutateSite((d) => { d.settings.heroSlides[index].badge = e.target.value; })}/></div></div>)}</div><button className="cmc-add" onClick={() => mutateSite((d) => { d.settings.heroSlides.push(structuredClone(d.settings.heroSlides.at(-1)!)); })}><Glyph name="plus"/>Agregar diapositiva</button></article>

          <article className="cmc-panel cmc-editor"><div className="cmc-panel-heading"><div><h3>Misión, visión y valores</h3></div><span className="cmc-tag">Sección Nosotros</span></div><div className="cmc-fields cols-2"><Textarea label="Misión" rows={6} value={site.settings.corporateIdentity.mission} onChange={(e) => mutateSite((d) => { d.settings.corporateIdentity.mission = e.target.value; })}/><Textarea label="Visión" rows={6} value={site.settings.corporateIdentity.vision} onChange={(e) => mutateSite((d) => { d.settings.corporateIdentity.vision = e.target.value; })}/></div><div className="cmc-repeat-grid">{site.settings.corporateIdentity.values.map((value, index) => <div className="cmc-repeat" key={index}><div><b>Valor {index + 1}</b><button aria-label={`Eliminar valor ${index + 1}`} onClick={() => mutateSite((d) => { if (d.settings.corporateIdentity.values.length > 1) d.settings.corporateIdentity.values.splice(index, 1); })}><Glyph name="trash"/></button></div><Input label="Nombre" value={value.title} onChange={(e) => mutateSite((d) => { d.settings.corporateIdentity.values[index].title = e.target.value; })}/><Textarea label="Descripción" rows={3} value={value.description} onChange={(e) => mutateSite((d) => { d.settings.corporateIdentity.values[index].description = e.target.value; })}/></div>)}</div><button className="cmc-add" onClick={() => mutateSite((d) => { d.settings.corporateIdentity.values.push({ title: "Nuevo valor", description: "Describe cómo se aplica este principio en CometaLink." }); })}><Glyph name="plus"/>Agregar valor</button></article>

          <article className="cmc-panel cmc-editor"><div className="cmc-panel-heading"><div><h3>Oferta comercial</h3></div><span className="cmc-tag">{site.plans.length} planes</span></div><div className="cmc-repeat-grid plans">{site.plans.map((plan, index) => <div className="cmc-repeat" key={index}><div><b>Plan {index + 1}</b><button type="button" aria-label={`Eliminar plan ${index + 1}`} onClick={() => mutateSite((d) => { if (d.plans.length > 1) d.plans.splice(index, 1); })}><Glyph name="trash"/></button></div><div className="cmc-fields cols-2"><Input label="Nombre" value={plan.name} onChange={(e) => mutateSite((d) => { d.plans[index].name = e.target.value; })}/><Input label="Identificador" value={plan.id} onChange={(e) => mutateSite((d) => { d.plans[index].id = e.target.value; })}/><Input label="Velocidad Mbps" type="number" value={plan.speed} onChange={(e) => mutateSite((d) => { d.plans[index].speed = Number(e.target.value); })}/><Input label="Mensualidad MXN" type="number" value={plan.price} onChange={(e) => mutateSite((d) => { d.plans[index].price = Number(e.target.value); })}/></div><div className="cmc-fields cols-2"><Input label="Descripción para streaming" value={plan.streaming} onChange={(e) => mutateSite((d) => { d.plans[index].streaming = e.target.value; })}/><Input label="Descripción para videojuegos" value={plan.gaming} onChange={(e) => mutateSite((d) => { d.plans[index].gaming = e.target.value; })}/></div><Input label="Frase comercial" value={plan.tagline} onChange={(e) => mutateSite((d) => { d.plans[index].tagline = e.target.value; })}/><Textarea label="Características (una por línea)" rows={4} value={plan.features.join("\n")} onChange={(e) => mutateSite((d) => { d.plans[index].features = e.target.value.split("\n"); })}/><label className="cmc-check"><input type="checkbox" checked={Boolean(plan.popular)} onChange={(e) => mutateSite((d) => { d.plans[index].popular = e.target.checked; })}/><span>Marcar como más elegido</span></label></div>)}</div><button className="cmc-add" onClick={() => mutateSite((d) => { d.plans.push({ id: `plan-${crypto.randomUUID().slice(0, 8)}`, name: "Nuevo plan", speed: 50, price: 0, tagline: "", popular: false, features: ["Velocidad simétrica"], streaming: "", gaming: "" }); })}><Glyph name="plus"/>Agregar plan</button></article>

          <article className="cmc-panel cmc-editor"><div className="cmc-panel-heading"><div><h3>Emisoras y mapa de cobertura</h3></div><span className="cmc-tag">{site.towers.length} emisoras</span></div><div className="cmc-table-scroll"><table className="cmc-edit-table"><thead><tr><th>Nombre</th><th>Municipio</th><th>C.P.</th><th>Latitud</th><th>Longitud</th><th>Radio km</th><th/></tr></thead><tbody>{site.towers.map((tower, index) => <tr key={`${tower.id}-${index}`}><td><input value={tower.name} aria-label="Nombre" onChange={(e) => mutateSite((d) => { d.towers[index].name = e.target.value; })}/></td><td><input value={tower.municipality} aria-label="Municipio" onChange={(e) => mutateSite((d) => { d.towers[index].municipality = e.target.value; })}/></td><td><input value={tower.postalCode} aria-label="Código postal" onChange={(e) => mutateSite((d) => { d.towers[index].postalCode = e.target.value; })}/></td><td><input type="number" step="any" value={tower.lat} aria-label="Latitud" onChange={(e) => mutateSite((d) => { d.towers[index].lat = Number(e.target.value); })}/></td><td><input type="number" step="any" value={tower.lng} aria-label="Longitud" onChange={(e) => mutateSite((d) => { d.towers[index].lng = Number(e.target.value); })}/></td><td><input type="number" step=".1" value={tower.radiusKm} aria-label="Radio" onChange={(e) => mutateSite((d) => { d.towers[index].radiusKm = Number(e.target.value); })}/></td><td><button aria-label="Eliminar emisora" onClick={() => mutateSite((d) => { if (d.towers.length > 1) d.towers.splice(index, 1); })}><Glyph name="trash"/></button></td></tr>)}</tbody></table></div><button className="cmc-add" onClick={() => mutateSite((d) => { d.towers.push({ id: `torre-${crypto.randomUUID().slice(0, 8)}`, name: "Nueva emisora", municipality: "Teotihuacán", postalCode: "", lat: 19.689, lng: -98.88, radiusKm: 4 }); })}><Glyph name="plus"/>Agregar emisora</button></article>

          <article className="cmc-panel cmc-editor"><div className="cmc-panel-heading"><div><h3>Preguntas frecuentes</h3></div></div><div className="cmc-repeat-grid">{site.faqs.map((faq, index) => <div className="cmc-repeat" key={index}><div><b>Pregunta {index + 1}</b><button type="button" aria-label={`Eliminar pregunta ${index + 1}`} onClick={() => mutateSite((d) => { d.faqs.splice(index, 1); })}><Glyph name="trash"/></button></div><Input label="Pregunta" value={faq.question} onChange={(e) => mutateSite((d) => { d.faqs[index].question = e.target.value; })}/><Textarea label="Respuesta" rows={4} value={faq.answer} onChange={(e) => mutateSite((d) => { d.faqs[index].answer = e.target.value; })}/></div>)}</div><button className="cmc-add" onClick={() => mutateSite((d) => { d.faqs.push({ question: "Nueva pregunta", answer: "Escribe aquí la respuesta." }); })}><Glyph name="plus"/>Agregar pregunta</button></article>
<article className="cmc-panel cmc-editor"><div className="cmc-panel-heading"><h3>Aviso público de mantenimiento</h3></div><p>La activación del modo de mantenimiento se administra en Parámetros del CMC original. Aquí puedes editar su aviso.</p><div className="cmc-fields cols-2"><Input label="Título del aviso" value={site.settings.maintenance.title} onChange={event => mutateSite(draft => { draft.settings.maintenance.title = event.target.value; })}/><Input label="Imagen del aviso" value={site.settings.maintenance.image} onChange={event => mutateSite(draft => { draft.settings.maintenance.image = event.target.value; })}/></div><Textarea label="Mensaje del aviso" rows={3} value={site.settings.maintenance.message} onChange={event => mutateSite(draft => { draft.settings.maintenance.message = event.target.value; })}/></article>
<article className="cmc-panel cmc-editor"><div className="cmc-panel-heading"><h3>Textos de cada sección</h3></div><p className="cmc-editor-help">Abre una sección para editar sus botones, etiquetas y mensajes.</p>{pageCopySections.map(([prefix, , title]) => { const fields = Object.entries(site.settings.pageCopy).filter(([key]) => key.startsWith(prefix + "_")); return <details className="cmc-copy-section" key={prefix}><summary>{title}<span>{fields.length} textos</span></summary><div className="cmc-fields cols-2">{fields.map(([key,value]) => { const props = { label: pageCopyLabel(key,prefix), value, onChange: (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => mutateSite(draft => { draft.settings.pageCopy[key] = event.target.value; }) }; return value.length > 82 || /(descripcion|introduccion|consentimiento|mensaje|derecho_|aviso)/.test(key) ? <Textarea key={key} {...props} rows={3}/> : <Input key={key} {...props}/>; })}</div></details>; })}</article>
</div></fieldset></>; }
